import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"01 | 快速开始：由简入繁，从解答到解决","description":"","frontmatter":{},"headers":[{"level":2,"title":"提问 5 要素","slug":"提问-5-要素","link":"#提问-5-要素","children":[{"level":3,"title":"Part 1：观察练习","slug":"part-1-观察练习","link":"#part-1-观察练习","children":[]},{"level":3,"title":"Part 2：凯利判据和提问 5 要素","slug":"part-2-凯利判据和提问-5-要素","link":"#part-2-凯利判据和提问-5-要素","children":[]}]},{"level":2,"title":"怎么持续对话？","slug":"怎么持续对话","link":"#怎么持续对话","children":[]},{"level":2,"title":"从解答，到解决","slug":"从解答-到解决","link":"#从解答-到解决","children":[]},{"level":2,"title":"小黑板","slug":"小黑板","link":"#小黑板","children":[]},{"level":2,"title":"踏浪扬帆","slug":"踏浪扬帆","link":"#踏浪扬帆","children":[]}],"relativePath":"零基础GPT应用入门课/01｜快速开始：由简入繁，从解答到解决.md","filePath":"零基础GPT应用入门课/01｜快速开始：由简入繁，从解答到解决.md","lastUpdated":1795561467000}'),s={name:"零基础GPT应用入门课/01｜快速开始：由简入繁，从解答到解决.md"};function n(p,e,E,o,r,h){return i(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="_01-快速开始-由简入繁-从解答到解决" tabindex="-1">01 | 快速开始：由简入繁，从解答到解决 <a class="header-anchor" href="#_01-快速开始-由简入繁-从解答到解决" aria-label="Permalink to &quot;01 | 快速开始：由简入繁，从解答到解决&quot;">​</a></h1><p>你好，我是键盘，我们开始来撩 ChatGPT。</p><p>好不容易来到 ChatGPT 的新世界传送门口，相信很多人就愣住了。一半是兴奋，一半是落寞：“WOW？就这样？我在哪，我该说点什么？”虽然惊叹于网上不少 ChatGPT 的炫酷操作，但是亲赴战场了，却不知道怎么开始。</p><p>关于这一句“开场白”，大家都遇到了哪些共性问题呢？我通过身边的朋友了解、提炼了一下：</p><ul><li><p>我要用英语吗？</p></li><li><p>不知道怎么写 prompt，有什么公式或者简单好用的技巧？</p></li><li><p>ChatGPT 的结果总是和预期有偏差，怎么解决？</p></li><li><p>ChatGPT 话总是没说完，怎么应对？</p></li><li><p>现在 AI 们这么卷，我实在来不及体验了，学习这些知识能否复用？</p></li><li><p>提交给 AI 的提示词，包括像 Midjourney 这样的文生图人工智能，都被称为 prompt。</p></li></ul><p>本节课，我们立足于实践案例，由简入繁，一一解决这些问题。无论是否有基础，通过这一节课，你都会拨开迷雾，让自己有个清晰的方向。</p><h2 id="提问-5-要素" tabindex="-1">提问 5 要素 <a class="header-anchor" href="#提问-5-要素" aria-label="Permalink to &quot;提问 5 要素&quot;">​</a></h2><p>作为当今顶流大语言模型之一，ChatGPT 支持任何自然语言，请放心用中文开始。如果你也关注 ChatGPT 的核心竞争对手们，Calude 支持，谷歌 Bard 也即将支持。对于比普通话更困难的闽南语，手机端 ChatGPT 也能通过内置的 Whisper 听懂。</p><p>既然 AI 自动解决了语言障碍，那我们就能聚焦真正重要的问题了。首先来看搜索时代可以延续的做法，当你搜索解惑的时候，通常是这个浓缩的公式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>关键词/一句话</span></span></code></pre></div><p>举两个例子。</p><ul><li><p>关键词，“夜曲一响”。想要了解周杰伦《夜曲》封神那一晚的故事，浏览器会自动给你补全“，上台领奖”，或者其他关联的结果，但也仅限于知识库里已有的内容。</p></li><li><p>一句话，“客厅适合养什么懒人绿植？”。想要了解适合自己的客厅的家居植物搭配方案，会被指引到不同的平台或博文。梳理要点之后，可能会考虑怎么买。</p></li></ul><p>时代变了，套路没有变。如今，我们通过提示词来解惑，它由 5 个要素组成：</p><ul><li>主题 + 数量 + 细节 + 方式 + 格式</li></ul><h3 id="part-1-观察练习" tabindex="-1">Part 1：观察练习 <a class="header-anchor" href="#part-1-观察练习" aria-label="Permalink to &quot;Part 1：观察练习&quot;">​</a></h3><p>下面我提供一个快速的案例，做一个小小的主观开放题，之后再逐步拆解这 5 个要素。先看我的描述：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/1.png" alt=""></a></p><ul><li>完整公式对应的 prompt 实例</li></ul><p>你需要观察 2 个重点：</p><ol><li><p>对比“写一份题目叫《GPT 颠覆教育》的 PPT”，输出的精度是否明显提升？</p></li><li><p>这个输出结果有没有超出你的预期？</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/2.png" alt=""></a></p><ul><li>“一句话需求”版本</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/3.png" alt=""></a></p><ul><li>PPT大纲：GPT 的教育颠覆力量</li></ul><p>相信结果范例已经给到你一个清晰的初步印象：只要细节描述得当，一次回车 = 一份可交付的文稿。在此基础上，你可以快速地进行细化，或者通过工具转换，拿到最终的 PPT。</p><p>ChatGPT 不仅一键改变了生产力，还重塑了生产关系——机械执行留给机器，运筹帷幄由你掌控。现在你可以悠闲地冲一杯咖啡，聚焦思考公式里的 5 个要素，怎么去灵活组合应用，而不再是评估人力怎么消耗在 PPT 制作上了。</p><p>AI 时代的处世法则：能动口，尽量不动手。</p><h3 id="part-2-凯利判据和提问-5-要素" tabindex="-1">Part 2：凯利判据和提问 5 要素 <a class="header-anchor" href="#part-2-凯利判据和提问-5-要素" aria-label="Permalink to &quot;Part 2：凯利判据和提问 5 要素&quot;">​</a></h3><p>现在，我们就开始提问 5 要素的组合练习。</p><ul><li>主题：是什么 / 做什么。</li></ul><p>要想从“一杯茶、一支烟、一份文稿磨半天”有效转变为“一键出稿”，最核心的要素当数“清晰、明确的主题描述”——我到底要的是什么？ChatGPT 需要帮我做什么？</p><p>人人都可以用“是什么 / 做什么”这个结构说明白，而且不用刻意讲究标点符号。</p><ul><li><p>Prompt</p></li><li><p>什么是凯利判据</p></li><li><p>🤖️ ChatGPT</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/4.png" alt=""></a></p><p>主题还有很多常用的提问方式，围绕内核“是什么 / 做什么”，用自然语言发挥就是：XX 是什么？我们来谈谈 XX。为什么 XX？你怎么看 XX？如果 XX 会怎样？写 1 份 XX。</p><p>而 ChatGPT 倾向于使用“总 - 分 - 总”的结构来分析，小学语文的套路，却出奇地有条理。</p><ul><li>数量：要多少个参考？</li></ul><p>在主题要素的基础上，你既可以加入数量要求，也可以分拆多次来提问。为何需要数量？因为不指定，那就只有一个参考。</p><ul><li>整合的方式，Prompt</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>什么是凯利判据，请提供 3 个应用实例</span></span></code></pre></div><ul><li>🤖️ ChatGPT</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/5.png" alt=""></a></p><p>你看，多说半句就可进可退了，但由于输出的长度也有局限，数量要求不宜过多。不同类型的任务都有各自的最优解，建议你根据实际情况多尝试。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/6.png" alt=""></a></p><ul><li><p>数量最优解</p></li><li><p>细节：具体说。</p></li></ul><p>这一步主要是从数量要求延伸到所有细节相关的要求。我们回到问题“ChatGPT 的结果总是和预期有偏差，怎么解决？”，本质上是一样的，只要你不提期望的细节，结果必然泛泛而谈。</p><ul><li><p>Prompt</p></li><li><p>凯利判据是什么？</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需要极简洁的背景故事和 (信息源链接)[link]</span></span>
<span class="line"><span>给出 1 个应用指导</span></span></code></pre></div><ul><li><p>重点部分加粗强调</p></li><li><p>🤖️ ChatGPT</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/7.png" alt=""></a></p><ul><li>方式：怎么来？</li></ul><p>解决了主题、数量和细节，你的提问（prompt）已经是最小可用结构了。但是实际使用中肯定还有突出的问题没有覆盖解决，最常见的有 2 个：</p><ol><li><p>输出的重点被长篇大论淹没，要花不少时间调教。（BTW，ChatGPT 对比 GPT-4 会显得更加啰嗦）</p></li><li><p>结果材料无法拿去跟你的受众人群精准地沟通，基本在及格线徘徊。</p></li></ol><p>这里我给你提供 3 种实用方式来引导 ChatGPT 修正：基于偏好 / 感受、基于目标受众、基于课题创造性。</p><p>第一种：基于偏好 / 感受。我特意撩 ChatGPT 得到了一些“基于感受”的具体参考，你可以直接在自己的 prompt 里加入相应的内容。</p><ul><li><p>正式：使用正式的词汇、文雅的语句和适当的礼貌用语来表达。</p></li><li><p>幽默：使用幽默的词汇、俏皮的语句和双关语来增加一些幽默感。友好：使用友好、亲切的词汇和句子结构来传达友好的语气严肃：使用严肃的词汇和表达方式来传达认真或庄重的语气。知识性：使用专业术语、详细解释和确切的事实来传达专业知识或学术语气。鼓励：使用鼓励性的语言、积极的表达和支持性的观点来传达鼓励的语气。建议：使用建议性的语气、指导性的表达和合理的建议来传达建议的语气。</p></li><li><p>请记住，语气的设定通常是通过选择合适的词汇和表达方式来实现的，而不是直接指定语气参数。你可以尝试使用特定的句子结构、情感词汇和修饰词来实现所需的语气效果。同时，上下文对于理解所需语气的重要性也不可忽视，因为适当的回应应该与先前的对话和背景一致。</p></li></ul><p>还有一组常用的 3 段组合，让 ChatGPT 的输出不再千篇一律。</p><ul><li><p>Prompt</p></li><li><p>用简洁的语言、积极的语气、英文输出。</p></li></ul><p>这段 prompt 里“简洁的语言”的描述，针对的就是重点容易被长文本淹没的问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/8.png" alt=""></a></p><ul><li>3 种细节指定方式的组合</li></ul><p>第二种：基于目标受众。作为可交付的材料，它一定是需要跟目标受众去沟通的。面向的可能是接收工作汇报的老板、产品的客户群体，甚至是你自己。所以，你还要注入目标受众的要求，让 ChatGPT 更懂你。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/9.png" alt=""></a></p><ul><li>针对 10 岁孩子、高中生、菜市场大妈的不同受众输出</li></ul><p>第三种：基于课题创造性。学习 newBing 的简洁分类即可满足使用：精确、平衡以及创意。底层逻辑是由熵值参数 temperature 驱动，其数值在[0,1]之间，越大表示选取的候选词越随机，回复越具有不确定性。创意性任务越大越好，精确性任务越小越好。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/10.png" alt=""></a></p><ul><li>newBing 的 3 种风格分类</li></ul><p>举个需要创造性的例子：</p><ul><li><p>Prompt</p></li><li><p>用富有想象力的方式，写一段暖场的冷笑话</p></li><li><p>🤖️ ChatGPT</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/11.png" alt=""></a></p><ul><li>格式：怎么秀？</li></ul><p>“主题 + 数量 + 细节 + 方式”解决了核心内容可用性，那 ChatGPT 能不能像设计师一样给我输出一份好看的材料呢？当然可以，安排！我们说几个典型场景。</p><ol><li>日常办公： PPT、脑图、流程图，通通要求输出 markdown，自己再转换一下，就可以曲线救国了。（例：GPT 生成脑图的 markdown 代码 ▸ 在支持 markdown 的脑图工具中粘贴代码生成。）</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/12.png" alt=""></a></p><ul><li>用 GPT 的套路撩隔壁联网的 Bard秒速将视频重点提炼为脑图</li></ul><ol start="2"><li>数据可视化：让 GPT 联动 Python 或者 Excel，可生成专业级的可视化图表。2D、3D、可交互和动态，应有尽有，我们保存就好。（例：GPT 生成 csv 数据 ▸ Excel 中将数据转换成图表。）</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/13.png" alt=""></a></p><ul><li>可交互图表</li></ul><ol start="3"><li>教育和投资领域：涉及很多公式，直接让 GPT 直观渲染，可读性和辨识度都很优秀。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/14.png" alt=""></a></p><ul><li>公式渲染</li></ul><p>以上 5 要素，你可以灵活组合去应用，相信结果的质量一定会更上一层楼。最后我们想了解“凯利判据”的 prompt 可能就是：</p><ul><li>用简洁的语言讲解凯利判据。要求：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 需要极简洁的背景故事和 (信息源链接)[link]</span></span>
<span class="line"><span>- 用表格给出 3 个应用指导</span></span>
<span class="line"><span>- 重点部分加粗强调</span></span>
<span class="line"><span>- 小白能理解的方式</span></span></code></pre></div><p>这样，就足以生成一份不会跑偏，对你胃口，详细但不啰嗦的 AI 回复了。</p><h2 id="怎么持续对话" tabindex="-1">怎么持续对话？ <a class="header-anchor" href="#怎么持续对话" aria-label="Permalink to &quot;怎么持续对话？&quot;">​</a></h2><p>用 GPT 系列模型的小伙伴都会遇到一个问题：频繁地中断。很多新手不知道怎么有效应对。首先明白 2 个点：中断是 ChatGPT 的常态、对话是可持续的。</p><p>无论有没有中断，你都可以持续和 ChatGPT 沟通，而对于中断，在 GPT-4 中只需要说“继续”，ChatGPT 就会倾向于从头开始补全，没关系，我们使用“精确继续 prompt” 来应对：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/15.png" alt=""></a></p><ul><li>向 ChatGPT 明确如何“继续”</li></ul><p>后来官方也特意补了个按钮来解决中断，实际体验是无缝衔接的，但不是所有中断都会触发这个按钮。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/16.png" alt=""></a></p><ul><li>0518 官方上线的“继续”</li></ul><p>这里补充一点，交谈的过程，我推荐逐步推进的方式：先试探，再逐步深入去补充，往往比单次输入的效果好得多。因为很有可能一开始它并不懂，但是装懂。</p><p>在下面 Golden Circle（一种思维模式） 的实例中，我通过 3 轮对话迭代试探了 ChatGPT 对这个概念的理解，再让它深入更具体的任务。其实前两次迭代使用中文译名它都没有理解，也就是说，假如没有这个前置的试探，一开始就注定结果是无效的。</p><ul><li><p>3 轮对话：</p></li><li><p>你知道黄金三圈吗 🤷‍♀️你知道黄金三圈思维框架吗 🤷‍♀️你知道 Golden Circle 思维框架吗 ✅</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/17.png" alt=""></a></p><ul><li>Golden Circle</li></ul><p>一句话：慢慢来，比较快。</p><p>逐步推进的过程，我也给你分享 3 个最高性价比的提效操作，它们长得像辅助，实际却是战士。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/18.png" alt=""></a></p><ul><li>一键提效</li></ul><ol><li><p>Stop Generating（停止）：开头不符合预期时，不需要浪费时间，尤其是长输出任务。</p></li><li><p>Regenerate Response（重新生成）：将输出的不稳定性变成优势。</p></li><li><p>Edit（编辑 prompt）：没必要新起会话，点一下就能迭代原 prompt。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/19.png" alt=""></a></p><ul><li>3 个提效操作</li></ul><h2 id="从解答-到解决" tabindex="-1">从解答，到解决 <a class="header-anchor" href="#从解答-到解决" aria-label="Permalink to &quot;从解答，到解决&quot;">​</a></h2><p>ChatGPT 从根本上改变了人们答疑解惑的方式，更深远的影响则是重塑了解决问题的过程。如今人人都可以有一位智能提效助手，问题是怎么点亮 TA 自带的六边形战士光芒，让它不止于解惑。</p><p>我整理了一个思维框架 SII 来解决这个问题：</p><ul><li><p>S（See），看见。输入完备的信息，明确你的需求、受众、期望目标，让 GPT“懂”你。GPT是怎么“懂”的？压缩信息，提炼成知识。（例：生成 PPT 大纲）</p></li><li><p>I（Insight），洞察。结合自己的专业知识，让 GPT 提供有深度的洞见。GPT 是用来思考的，而不是冷冰冰地计算。它的核心价值点之一就是 TA 能提供的洞察。（例：PPT 的细节指导，我该怎么用？）</p></li><li><p>I（Impact），影响。SI 服务于智能解答，但最后我们还要解决问题，那么你就要引导 GPT将洞察再转化为有用的行动指引，比如说 prompt：“将 &lt; 上述结论 &gt; 整合成一份 Python 解决方案，然后用列表输出使用指导，我没有计算机基础。”（例：搞定最终的 PPT）</p></li></ul><p>当然，在使用的过程中，我们还会介入提示词工程和持续迭代来有效提升输出的质量和效率。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/20.png" alt=""></a></p><ul><li>思维模型 SII</li></ul><h2 id="小黑板" tabindex="-1">小黑板 <a class="header-anchor" href="#小黑板" aria-label="Permalink to &quot;小黑板&quot;">​</a></h2><p>这节课，我们通过分析“开场白”的共性问题，借助“凯利判据”的案例逐步深入，讲解了可以灵活组合的提问 5 要素：主题、数量、细节、方式、格式。然后学习了“先试探，再逐步深入”的方式来进一步提升输出质量，通过精确继续 prompt。一个小技巧是，“从 &lt; 什么部分 &gt; 继续”来鼓励 ChatGPT “迭迭”不休，频繁中断的问题得到有效解决。迭代过程中，我也提出了 3 个实用的提效操作“停止”“重新生成”和“编辑”，将 ChatGPT 的劣势用成优势。最后，我们不止步于解答，通过思维框架 SII，让 ChatGPT 真正成为了一位高质量的提效助手。</p><p>最后我想和你聊聊实例中的凯利判据。它是 1956 年 J. L. Kelly Jr 提出的一个概念，是概率论和跨期投资组合选择中确定一系列投资的最优规模的一个公式。</p><p>但同时，它也是一种快速上手 ChatGPT 的方法。</p><p>前者通过计算数学期望来知己知彼，分配最佳的投注比，得到最好的收益，并且确保永远不会出局。假如期望是负数，结果必败，则应该避免参与。</p><p>而使用 ChatGPT 是一门人机交流的艺术。通过 5 要素盘点我们的信息和预期，才能有效引导ChatGPT 给出丰满可用的结果。“先试探，再深入”则是一种期望校正策略，一旦 AI 存在不了解的背景信息，必然会导致结果跑偏。</p><p>同样的方法，你完全可以应用到其他 AI 的快速实践，以及工作、学习和投资等领域，让 GPT给出真知灼见，携手人工智能有效解决问题。</p><p>要点：</p><ul><li><p>AI 时代的处世法则，能动口，尽量不动手。</p></li><li><p>想要输出结果丰满好用，加入“主题”的相关的背景、要求、期望的目标等细节。</p></li><li><p>不同类型的输出任务，输出数量有最优解。</p></li><li><p>多种细节指定方式，让 GPT 更懂你。</p></li><li><p>一步一步交流，慢慢来，比较快。</p></li><li><p>提前停止、重来、编辑——1 键 3 连，提效立竿见影。</p></li><li><p>提供洞察，是 AI 的核心价值点之一，侧重将 TA 用于思考，而不是计算。</p></li><li><p>思维框架 SII，帮你清晰地理解 ChatGPT 解决问题的逻辑。</p></li></ul><h2 id="踏浪扬帆" tabindex="-1">踏浪扬帆 <a class="header-anchor" href="#踏浪扬帆" aria-label="Permalink to &quot;踏浪扬帆&quot;">​</a></h2><p>如果用逐步提问的方式，通过完整的会话来解决一个工作总结 PPT 大纲，你会怎么说呢？</p><p>期待在评论区看到你的思考或感受分享，戳此加入课程交流群，也欢迎你将这节课分享给感兴趣的朋友们，咱们以后就 ChatPPT：这里大一点，那里字少一点。</p><p>我们下节课再会。</p>`,125)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
